-- RBAC: hapus akun PENGURUS lama lalu murnikan kolom role menjadi 13 role sesuai Use Case Diagram
DELETE FROM `user` WHERE CAST(`role` AS CHAR) = 'PENGURUS';
ALTER TABLE `user` MODIFY `role` ENUM('DONATUR', 'PENERIMA_BANTUAN', 'ADMIN_SISTEM', 'BIDANG_INFORMATIKA', 'KETUA', 'BENDAHARA', 'SEKRETARIS', 'BIDANG_SOSIAL', 'BIDANG_PENDIDIKAN', 'BIDANG_KESEHATAN', 'HUMAS', 'PENGAWAS', 'PEMBINA') NOT NULL;
